UPDATE REP_TRADE_INFO as A, ( select ID, ASSET_ID, ASSET_NAME, TRADE_COUNTY, TRADE_DATE, TRADE_AMT, TRADE_TYPE, BUY_PART, SALE_PART, PS, STATUS, IS_RELATION_TRADE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, EXPIRE_RATE, CONTRACT_NO, PROD_ID, PRIN_AMT from ( select TEMP.* from (
SELECT #{item.id,jdbcType=VARCHAR} ID, #{item.assetId,jdbcType=VARCHAR} ASSET_ID, #{item.assetName,jdbcType=VARCHAR} ASSET_NAME, #{item.tradeCounty,jdbcType=VARCHAR} TRADE_COUNTY, #{item.tradeDate,jdbcType=DATE} TRADE_DATE, #{item.tradeAmt,jdbcType=DECIMAL} TRADE_AMT, #{item.tradeType,jdbcType=VARCHAR} TRADE_TYPE, #{item.buyPart,jdbcType=VARCHAR} BUY_PART, #{item.salePart,jdbcType=VARCHAR} SALE_PART, #{item.ps,jdbcType=VARCHAR} PS, #{item.status,jdbcType=VARCHAR} STATUS, #{item.isRelationTrade,jdbcType=VARCHAR} IS_RELATION_TRADE, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.expireRate,jdbcType=DECIMAL} EXPIRE_RATE, #{item.contractNo,jdbcType=VARCHAR} CONTRACT_NO, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.prinAmt,jdbcType=DECIMAL} PRIN_AMT FROM dual
) TEMP ) de ) AS B set A.ASSET_ID = B.ASSET_ID, A.ASSET_NAME = B.ASSET_NAME, A.TRADE_COUNTY = B.TRADE_COUNTY, A.TRADE_DATE = B.TRADE_DATE, A.TRADE_AMT = B.TRADE_AMT, A.TRADE_TYPE = B.TRADE_TYPE, A.BUY_PART = B.BUY_PART, A.SALE_PART = B.SALE_PART, A.PS = B.PS, A.STATUS = B.STATUS, A.IS_RELATION_TRADE = B.IS_RELATION_TRADE, A.CREATE_USER = B.CREATE_USER, A.CREATE_DEPT = B.CREATE_DEPT, A.CREATE_TIME = B.CREATE_TIME, A.UPDATE_USER = B.UPDATE_USER, A.UPDATE_TIME = B.UPDATE_TIME, A.EXPIRE_RATE = B.EXPIRE_RATE, A.CONTRACT_NO = B.CONTRACT_NO, A.PROD_ID = B.PROD_ID, A.PRIN_AMT = B.PRIN_AMT where A.ID = B.ID;
insert into REP_TRADE_INFO(ID, ASSET_ID, ASSET_NAME, TRADE_COUNTY, TRADE_DATE, TRADE_AMT, TRADE_TYPE, BUY_PART, SALE_PART, PS, STATUS, IS_RELATION_TRADE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, EXPIRE_RATE, CONTRACT_NO, PROD_ID, PRIN_AMT) select ID, ASSET_ID, ASSET_NAME, TRADE_COUNTY, TRADE_DATE, TRADE_AMT, TRADE_TYPE, BUY_PART, SALE_PART, PS, STATUS, IS_RELATION_TRADE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, EXPIRE_RATE, CONTRACT_NO, PROD_ID, PRIN_AMT from ( select TEMP.* from (
SELECT #{item.id,jdbcType=VARCHAR} ID, #{item.assetId,jdbcType=VARCHAR} ASSET_ID, #{item.assetName,jdbcType=VARCHAR} ASSET_NAME, #{item.tradeCounty,jdbcType=VARCHAR} TRADE_COUNTY, #{item.tradeDate,jdbcType=DATE} TRADE_DATE, #{item.tradeAmt,jdbcType=DECIMAL} TRADE_AMT, #{item.tradeType,jdbcType=VARCHAR} TRADE_TYPE, #{item.buyPart,jdbcType=VARCHAR} BUY_PART, #{item.salePart,jdbcType=VARCHAR} SALE_PART, #{item.ps,jdbcType=VARCHAR} PS, #{item.status,jdbcType=VARCHAR} STATUS, #{item.isRelationTrade,jdbcType=VARCHAR} IS_RELATION_TRADE, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.expireRate,jdbcType=DECIMAL} EXPIRE_RATE, #{item.contractNo,jdbcType=VARCHAR} CONTRACT_NO, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.prinAmt,jdbcType=DECIMAL} PRIN_AMT FROM dual
) TEMP where not exists (select 1 from REP_TRADE_INFO CII where CII.ID = TEMP.ID) ) de ;
